B.acP=new A.j(B.fZ,[" \uc9c0\uc18d\uc801\uc778 \uc815\ud569\uc131 \ud655\uc778 \ub8e8\ud2f4\uc744 \uc2a4\uc2a4\ub85c \uc0ac\uc218\ud558\ub294 \ud0dc\ub3c4\uac00 \uacb0\uad6d \ud754\ub4e4\ub9ac\uc9c0 \uc54a\ub294 \uc2e4\ub825\uc744 \ub9cc\ub4ed\ub2c8\ub2e4."," \uc870\uae08\uc758 \uc784\uacc4\uc810(\ub2e4\uc74c \ub2e8\uacc4\ub85c \ub118\uc5b4\uac00\uae30 \uc704\ud574 \ud544\uc694\ud55c \ucd5c\uc18c\ud55c\uc758 \ud559\uc5c5 \ubc00\ub3c4)\ub9cc \ub118\uc5b4\uc11c\uba74 \uc0c1\uc704\uad8c \uc9c4\uc785\uc740 \uc2dc\uac04 \ubb38\uc81c\uc785\ub2c8\ub2e4."," \uad6c\uc870\uc801 \uc624\uc778(\uac1c\ub150\uc758 \ubf08\ub300\ub97c \uc798\ubabb \uc774\ud574\ud574 \uc624\ub2f5\uc744 \ub3c4\ucd9c\ud558\ub294 \ud604\uc0c1)\ub9cc \ubc14\ub85c\uc7a1\uc73c\uba74 \ubc18\ub4f1\uc758 \ud3ed\uc740 \uc608\uc0c1\ubcf4\ub2e4 \ud074 \uc218 \uc788\uc2b5\ub2c8\ub2e4."," \uc9c0\uae08 \ub2e4\uc9c0\ub294 \uae30\ucd08\uac00 \uc55e\uc73c\ub85c\uc758 \ubaa8\ub4e0 \ud559\uc2b5\uc758 \ubf08\ub300\uac00 \ub41c\ub2e4\ub294 \uc810\uc744 \uae30\uc5b5\ud574 \uc8fc\uc2dc\uae38 \ubc14\ub78d\ub2c8\ub2e4."," \uac00\ub2a5\uc131\uc740 \uc5b8\uc81c\ub098 \uc5f4\ub824 \uc788\uc73c\ub2c8, \uc624\ub298\uc758 \uc791\uc740 \uc2e4\ucc9c\uc774 \ub0b4\uc77c\uc758 \ud070 \ubcc0\ud654\ub85c \uc774\uc5b4\uc9c8 \uac83\uc785\ub2c8\ub2e4."],t.w)
B.a_V=s(["\ud2b9\ud788 {subject} \uacfc\ubaa9\uc5d0\uc11c\ub294 \uac1c\ub150 \uac04\uc758 \uc5f0\uacb0 \uad6c\uc870\ub97c \uc815\ud655\ud788 \ud30c\uc545\ud558\uace0 \uc788\uc5b4, \uc751\uc6a9\ubb38\uc81c\uc5d0\uc11c\ub3c4 \ud754\ub4e4\ub9bc \uc5c6\ub294 \uc815\ud569\uc131\uc744 \ubcf4\uc5ec\uc8fc\uace0 \uc788\uc2b5\ub2c8\ub2e4.","{subject} \uc601\uc5ed\uc758 \ucd5c\uadfc \ud480\uc774 \ud328\ud134\uc744 \uc0b4\ud3b4\ubcf4\uba74 \uae30\ubcf8 \uac1c\ub150 \ud655\uc778 \ub2e8\uacc4\ub97c \ucda9\uc2e4\ud788 \uac70\uce5c \ud754\uc801\uc774 \ub69c\ub837\ud558\uac8c \ub098\ud0c0\ub0a9\ub2c8\ub2e4.","\uc774\ubc88 {subject} \ud3c9\uac00\ub294 \uc2dc\uac04 \ubc30\ubd84\uacfc \ubb38\uc81c \ud574\uc11d \uc18d\ub3c4 \ubaa8\ub450 \uade0\ud615 \uc7a1\ud78c \ubaa8\uc2b5\uc744 \ubcf4\uc5ec, \uc2e4\uc804 \uac10\uac01\uc774 \uc0c1\ub2f9\ud788 \uc131\uc219\ud588\uc74c\uc744 \uc54c \uc218 \uc788\uc2b5\ub2c8\ub2e4."],t.s)
B.a14=s(["{subject} \uacfc\ubaa9\uc5d0\uc11c\ub294 \ud575\uc2ec \uac1c\ub150\uc758 \ubf08\ub300\ub294 \uc798 \uac16\ucd94\uc5b4\uc838 \uc788\uc73c\ub098, \uc870\uac74 \ud574\uc11d\uc758 \uc815\ubc00\ub3c4\uc5d0\uc11c \uc57d\uac04\uc758 \uac10\uc810 \uc694\uc778\uc774 \ud655\uc778\ub429\ub2c8\ub2e4.","{subject} \uc601\uc5ed\uc740 \uae30\ubcf8 \ubb38\uc81c\ud480\uc774\ub294 \uc548\uc815\uc801\uc774\ub098, \uace0\ub09c\ub3c4 \ubcc0\ud615 \ubb38\uc81c\ub85c \uac08\uc218\ub85d \ucc98\ub9ac \uc18d\ub3c4\uac00 \ub2e4\uc18c \ub290\ub824\uc9c0\ub294 \uacbd\ud5a5\uc774 \uad00\ucc30\ub429\ub2c8\ub2e4.","\uc774\ubc88 {subject} \ud3c9\uac00\uc5d0\uc11c\ub294 \uc804\ubc18\uc801\uc778 \uc774\ud574\ub3c4\ub294 \uc591\ud638\ud558\ub098, \uc138\ubd80 \uc870\uac74\uc744 \ub193\uce58\ub294 \uc2e4\uc218\uac00 \ubc18\ubcf5\uc801\uc73c\ub85c \ub098\ud0c0\ub0ac\uc2b5\ub2c8\ub2e4."],t.s)
B.a1X=s(["{subject} \uacfc\ubaa9\uc758 \uc624\ub2f5\uc744 \uc0b4\ud3b4\ubcf4\uba74 \ub300\ubd80\ubd84 \uad6c\uc870\uc801 \uc624\uc778(\uac1c\ub150\uc758 \ubf08\ub300\ub97c \uc798\ubabb \uc774\ud574\ud574 \uc624\ub2f5\uc744 \ub3c4\ucd9c\ud558\ub294 \ud604\uc0c1)\uc5d0\uc11c \ube44\ub86f\ub41c \uac83\uc73c\ub85c \ubcf4\uc785\ub2c8\ub2e4.","{subject} \uc601\uc5ed\uc5d0\uc11c\ub294 \uae30\ubcf8 \uac1c\ub150 \uc790\uccb4\ubcf4\ub2e4, \ubb38\uc81c \uc870\uac74\uc744 \uc815\ud655\ud788 \uc77d\uc5b4\ub0b4\ub294 \uacfc\uc815\uc5d0\uc11c \uc2e4\uc218\uac00 \ubc18\ubcf5\ub418\ub294 \uacbd\ud5a5\uc774 \ud655\uc778\ub429\ub2c8\ub2e4.","\uc774\ubc88 {subject} \ud3c9\uac00\ub294 \uc2dc\uac04 \ubd80\uc871\uc73c\ub85c \uc778\ud574 \ud6c4\ubc18\ubd80 \ubb38\ud56d\uc5d0\uc11c \uc9d1\uc911\ub825\uc774 \ud750\ud2b8\ub7ec\uc9c4 \ud754\uc801\uc774 \ub69c\ub837\ud558\uac8c \ub098\ud0c0\ub0a9\ub2c8\ub2e4."],t.s)
B.Y5=s(["{subject} \uacfc\ubaa9\uc758 \uc624\ub2f5 \ud328\ud134\uc740 \uac1c\ub150\uc758 \uae30\ubcf8 \ubf08\ub300\ub97c \uc624\ud574\ud55c \ucc44 \uc9c4\ub3c4\ub9cc \ub098\uac04 \ubd80\uc791\uc6a9\uc73c\ub85c \ud310\ub2e8\ub429\ub2c8\ub2e4.","{subject} \uc601\uc5ed\uc5d0\uc11c\ub294 \uc778\uc9c0\uc801 \uae30\ub9cc(\uc644\uc804\ud788 \uc774\ud574\ud558\uc9c0 \ubabb\ud588\uc74c\uc5d0\ub3c4 \uc774\ud574\ud588\ub2e4\uace0 \ucc29\uac01\ud558\ub294 \uc0c1\ud0dc)\uc774 \ubc18\ubcf5\uc801\uc73c\ub85c \uad00\ucc30\ub429\ub2c8\ub2e4.","\uc774\ubc88 {subject} \ud3c9\uac00\ub294 \uae30\ucd08 \uac1c\ub150 \ud655\uc778 \ub2e8\uacc4\uac00 \ucda9\ubd84\ud788 \uc774\ub8e8\uc5b4\uc9c0\uc9c0 \uc54a\uc740 \uc0c1\ud0dc\uc5d0\uc11c \ubb38\uc81c\ud480\uc774\ub85c \ub118\uc5b4\uac04 \ud754\uc801\uc774 \ub69c\ub837\ud569\ub2c8\ub2e4."],t.s)
B.a26=s(["{subject} \uacfc\ubaa9\uc740 \uae30\ucd08 \uc5b4\ud718 \uc2a4\ud0a4\ub9c8(\uc9c0\uc2dd\uc758 \uad6c\uc870\uc801 \ub124\ud2b8\uc6cc\ud06c)\uc870\ucc28 \uc544\uc9c1 \ubd88\uc548\uc815\ud55c \uc0c1\ud0dc\ub85c \ubcf4\uc774\uba70, \uadfc\ubcf8\uc801\uc778 \uc7ac\ud559\uc2b5\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.","{subject} \uc601\uc5ed\uc758 \uc624\ub2f5\uc740 \uac1c\ub150 \uc774\ud574 \uc5ec\ubd80\uc640 \ubb34\uad00\ud558\uac8c \uad11\ubc94\uc704\ud558\uac8c \ub098\ud0c0\ub098\uace0 \uc788\uc5b4, \ub2e8\uc6d0 \uc804\uccb4\ub97c \ucc98\uc74c\ubd80\ud130 \ub2e4\uc2dc \uc810\uac80\ud558\ub294 \uac83\uc774 \ubc14\ub78c\uc9c1\ud569\ub2c8\ub2e4.","\uc774\ubc88 {subject} \ud3c9\uac00\ub294 \ubb38\uc81c\ud480\uc774\ub7c9\ubcf4\ub2e4 \uae30\ubcf8 \uc6d0\ub9ac \uc774\ud574\uc5d0 \ud22c\uc785\ub41c \uc2dc\uac04\uc774 \ubd80\uc871\ud588\ub358 \uacb0\uacfc\ub85c \ud310\ub2e8\ub429\ub2c8\ub2e4."],t.s)
B.acQ=new A.j(B.fZ,[B.a_V,B.a14,B.a1X,B.Y5,B.a26],t.R)
B.ZW=s(["\uc774\ubc88 {type}\uc5d0\uc11c 90\uc810 \uc774\uc0c1\uc758 \uc6b0\uc218\ud55c \uc131\ucde8\ub97c \uae30\ub85d\ud55c \uac83\uc740, \uadf8\ub3d9\uc548 \uafb8\uc900\ud788 \uc313\uc544\uc628 \ud559\uc2b5\uc758 \ubc00\ub3c4\uac00 \ub208\uc5d0 \ubcf4\uc774\ub294 \uc131\uacfc\ub85c \uc774\uc5b4\uc84c\uc74c\uc744 \ubcf4\uc5ec\uc8fc\ub294 \ub9e4\uc6b0 \uace0\ubb34\uc801\uc778 \uacb0\uacfc\uc785\ub2c8\ub2e4.","90\uc810\ub300\uc758 \ub192\uc740 \uc810\uc218\ub294 \ud559\uc2b5\uc790\uc758 \uba54\ud0c0\uc778\uc9c0(\uc790\uc2e0\uc774 \ubb34\uc5c7\uc744 \uc54c\uace0 \ubb34\uc5c7\uc744 \ubaa8\ub974\ub294\uc9c0 \uc2a4\uc2a4\ub85c \uc810\uac80\ud558\ub294 \ub2a5\ub825) \uc218\uc900\uc774 \uc548\uc815\uc801\uc778 \uada4\ub3c4\uc5d0 \uc62c\ub77c\uc130\uc74c\uc744 \uc2dc\uc0ac\ud558\ub294 \uacb0\uacfc\uc785\ub2c8\ub2e4.","\uc774\ubc88 \ud3c9\uac00\uc5d0\uc11c \ud655\uc778\ub41c \uc6b0\uc218\ud55c \uc131\ucde8\ub294 \ub2e8\uae30\uac04\uc758 \uc694\ud589\uc774 \uc544\ub2c8\ub77c, \ubc18\ubcf5\uc801\uc778 \uac1c\ub150 \ud655\uc778\uacfc \uc624\ub2f5 \uc815\ub9ac\uac00 \ucd95\uc801\ub41c \uacb0\uacfc\ub85c \ud310\ub2e8\ub429\ub2c8\ub2e4."],t.s)
B.ZG=s(["\uc774\ubc88 {type}\uc5d0\uc11c 80\uc810\ub300\uc758 \uc548\uc815\uc801\uc778 \uc131\ucde8\ub97c \uae30\ub85d\ud55c \uac83\uc740 \ud559\uc2b5\uc758 \uae30\ubcf8\uae30\uac00 \ud0c4\ud0c4\ud558\uac8c \uc790\ub9ac\uc7a1\uc558\uc74c\uc744 \ubcf4\uc5ec\uc8fc\ub294 \uacb0\uacfc\uc785\ub2c8\ub2e4.","80\uc810\ub300 \uc810\uc218\ub294 \uac1c\ub150 \uc2a4\ud0a4\ub9c8(\uc9c0\uc2dd\uc758 \uad6c\uc870\uc801 \ub124\ud2b8\uc6cc\ud06c)\uac00 \uc0c1\ub2f9 \ubd80\ubd84 \uc815\ucc29\ub418\uc5c8\uc74c\uc744 \uc758\ubbf8\ud558\uba70, \uc870\uae08\ub9cc \ub354 \uc815\ubc00\ud558\uac8c \ub2e4\ub4ec\uc73c\uba74 \uc0c1\uc704\uad8c \uc9c4\uc785\uc774 \ucda9\ubd84\ud788 \uac00\ub2a5\ud55c \uc704\uce58\uc785\ub2c8\ub2e4.","\uc774\ubc88 \ud3c9\uac00\ub294 \uc548\uc815\uc801\uc778 \uc911\uc0c1\uc704\uad8c \uc131\ucde8\ub97c \ubcf4\uc5ec\uc8fc\uc5c8\uace0, \ud2b9\ud788 \uc2e4\uc218\ub97c \uc904\uc774\ub294 \ubc29\ud5a5\uc73c\ub85c \uc870\uae08\ub9cc \ubcf4\uc644\ud558\uba74 \ub208\uc5d0 \ub744\ub294 \ud5a5\uc0c1\uc744 \uae30\ub300\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4."],t.s)
B.a1l=s(["\uc774\ubc88 {type}\uc5d0\uc11c \uae30\ub85d\ud55c 70\uc810\ub300\uc758 \uc131\ucde8\ub294 \ud559\uc2b5\uc790\uac00 \uc9c0\ub2cc \uc2e4\uc81c \uc5ed\ub7c9\uc5d0 \ube44\ud574 \ub2e4\uc18c \uc544\uc26c\uc6b4 \uacb0\uacfc\ub85c \ud310\ub2e8\ub429\ub2c8\ub2e4.","70\uc810\ub300 \uc810\uc218\ub294 \uae30\ubcf8 \uac1c\ub150\uc740 \uac16\ucd94\uc5c8\uc73c\ub098 \uc2e4\uc804 \uc801\uc6a9 \uacfc\uc815\uc5d0\uc11c \uc815\ud569\uc131(\ub17c\ub9ac\uc801 \uc77c\uad00\uc131)\uc774 \ud754\ub4e4\ub9ac\ub294 \uc9c0\uc810\uc774 \uc788\uc74c\uc744 \uc2dc\uc0ac\ud569\ub2c8\ub2e4.","\uc774\ubc88 \ud3c9\uac00\ub294 \uac1c\ub150 \uc774\ud574\uc640 \uc2e4\uc804 \ubb38\uc81c\ud480\uc774 \uc0ac\uc774\uc758 \uac04\uadf9\uc774 \ub4dc\ub7ec\ub09c \uacb0\uacfc\ub85c, \uad6c\uc870\uc801\uc778 \uc810\uac80\uc774 \ud544\uc694\ud55c \uc2dc\uc810\uc785\ub2c8\ub2e4."],t.s)
B.a28=s(["\uc774\ubc88 {type}\uc5d0\uc11c \ub204\uc801\ub41c 60\uc810\ub300\uc758 \uc131\ucde8\ub3c4\ub294 \uad50\uacfc \uac1c\ub150\uc758 \uc815\ucc29 \ub2e8\uacc4\uc5d0\uc11c \uc608\uc0c1\ubcf4\ub2e4 \uae4a\uc740 \uade0\uc5f4\uc774 \ubc1c\uc0dd\ud588\uc74c\uc744 \ub098\ud0c0\ub0c5\ub2c8\ub2e4.","60\uc810\ub300 \uc810\uc218\ub294 \uac1c\ub150 \uc790\uccb4\ubcf4\ub2e4\ub294 \ud559\uc2b5 \uc2b5\uad00\uc758 \uad6c\uc870\uc801\uc778 \uc804\ud658\uc774 \uc2dc\uae09\ud568\uc744 \uc54c\ub9ac\ub294 \uc2e0\ud638\ub85c \ubc1b\uc544\ub4e4\uc774\ub294 \uac83\uc774 \ubc14\ub78c\uc9c1\ud569\ub2c8\ub2e4.","\uc774\ubc88 \ud3c9\uac00 \uacb0\uacfc\ub294 \uc870\uae09\ud568\ubcf4\ub2e4\ub294 \uae30\ucd08\ub97c \ub2e4\uc2dc \uc810\uac80\ud574\uc57c \ud558\ub294 \uc2dc\uc810\uc784\uc744 \uc54c\ub824\uc8fc\ub294 \uc9c0\ud45c\ub85c \ud574\uc11d\ud558\ub294 \uac83\uc774 \ud544\uc694\ud569\ub2c8\ub2e4."],t.s)
B.Y2=s(["\uc774\ubc88 {type}\uc5d0\uc11c \uae30\ub85d\ub41c \uc218\uce58\ub294 \uae30\ucd08 \uac1c\ub150 \uc815\ucc29 \ub2e8\uacc4\uc5d0\uc11c \uc804\ubc18\uc801\uc778 \uc7ac\uc870\uc815\uacfc \ubcf4\uc644\uc774 \uc2dc\uae09\ud568\uc744 \uac00\ub9ac\ud0a4\ub294 \uc9c4\ub2e8 \uacb0\uacfc\uc785\ub2c8\ub2e4.","\ud604\uc7ac \uc9c0\ud45c\ub294 \ud559\uc2b5 \uacfc\uc815 \uc804\uccb4\uc5d0 \uac78\uccd0 \uac1c\ub150\uc801\uc778 \uacf5\ubc31\uc774 \ub204\uc801\ub418\uc5c8\uc74c\uc744 \uacbd\uace0\ud558\uace0 \uc788\uc73c\uba70, \uc989\uac01\uc801\uc778 \ud559\uc2b5 \ub8e8\ud2f4\uc758 \uc7ac\uc815\ube44\uac00 \ud544\uc694\ud569\ub2c8\ub2e4.","\uc774\ubc88 \uacb0\uacfc\ub294 \uc2e4\ub9dd\ud558\uae30\ubcf4\ub2e4, \ud559\uc2b5 \ubc29\uc2dd \uc790\uccb4\ub97c \uadfc\ubcf8\uc801\uc73c\ub85c \uc7ac\uc810\uac80\ud560 \uc218 \uc788\ub294 \uae30\ud68c\ub85c \uc0bc\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4."],t.s)
B.acR=new A.j(B.fZ,[B.ZW,B.ZG,B.a1l,B.a28,B.Y2],t.R)
